function openDialog(title,body){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="dialog-close" data-action="close" aria-label="关闭">×</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function heading(eyebrow,title,subtitle,button=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`;}
function empty(emoji,title,text,button='',full=false){return `<div class="empty ${full?'full':''}"><div class="empty-icon">${emoji}</div><h3>${title}</h3><p>${text}</p>${button}</div>`;}
async function api(route,body,options={}){const headers={};if(body!==undefined){if(state)body={space_id:state.space.id,...body};headers['Content-Type']='application/json';if(state?.csrf)headers['X-CSRF-Token']=state.csrf;headers['Idempotency-Key']=options.key||requestId();}const {response:r,data}=await fetchJSON(new URL(`api/${route}`,location.href.split(/[?#]/)[0]),{method:body===undefined?'GET':'POST',headers,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});if(!r.ok){if(r.status===401&&state){state=null;renderAuth();}throw new Error(data.error||'请求未能完成');}return data;}
async function refresh(){
  let next=await api('state'+(space?'?space='+encodeURIComponent(space):''));
  if(!space){let remembered='';try{remembered=localStorage.getItem(roomMemoryKey(next.user.id))||'';}catch{}
    const selected=initialRoom(next,remembered);if(selected!==next.space.id)next=await api('state?space='+encodeURIComponent(selected));}
  const selectedChanged=state?.space.id!==next.space.id;
  if(selectedChanged)cleanupCelebration();state=next;progress.sync();space=state.space.id;if(selectedChanged)try{localStorage.setItem(roomMemoryKey(state.user.id),space);}catch{}
  const scope=state.user.id+':'+(state.family?.id||state.space.id),changed=scope!==perspectiveScope;
  const nextPerspective=roomPerspective(state,changed?'':perspective);
  if(changed||nextPerspective!==perspective){perspective=nextPerspective;perspectiveScope=scope;page=perspective==='manage'?'admin':'today';adminTab=state.space.status==='active'?'prizes':'redemptions';shopFilter='all';cardFilter='ready';adminCategory='all';}
  await community.load(page);render();if(!location.hash)community.notify();if(canAct())warmMessages();
}
async function boot(){try{status=await api('status');if(status.loggedIn){await refresh();await incoming();}else{authMode='welcome';renderAuth();const h=new URLSearchParams(location.hash.slice(1));if(h.has('auth-error'))toast(h.get('auth-error'));if(h.has('join'))joinDialog(h.get('join'));}window.StarlightStartup?.ready();offerNativeUpgrade();}catch(e){window.StarlightStartup?.ready();app.innerHTML=`<div class="loading"><span class="brand-symbol">✳</span><p>${esc(e.message)}</p><button class="btn" data-action="reload">重新连接</button></div>`;}}
async function incoming(){const h=new URLSearchParams(location.hash.slice(1));if(h.has('join')||pendingInvite){joinDialog(pendingInvite?.code||h.get('join'));return;}if(h.has('auth-error')){toast(h.get('auth-error'));history.replaceState(null,'',location.pathname);}if(h.has('github-bind')){bindPending=h.get('github-bind');openDialog('确认绑定 GitHub',`<p>将刚刚授权的 GitHub 绑定到当前账号「${esc(state.user.name)}」。</p><form id="github-confirm-form">${actions('确认绑定到这个账号')}</form>`);}if(h.has('redeem')){shareToken=h.get('redeem');try{const r=await api('share/inspect',{token:shareToken});fulfillDialog(r.card,shareToken);}catch(e){openDialog('这份心愿暂时打不开',`<p>${esc(e.message)}</p><button class="btn full-width" data-action="close">知道了</button>`);}}}
